    if not intervals:
        return []

    # Create a list to hold the merged intervals
    merged = []

    # Create a list of all start and end points
    points = []
    for start, end in intervals:
        points.append((start, 'start'))
        points.append((end, 'end'))

    # Sort the points by value, and for ties, end comes before start
    points.sort(key=lambda x: (x[0], x[1] == 'start'))

    # Traverse the points to merge intervals
    current_start = None
    current_end = None
    for point, type_ in points:
        if type_ == 'start':
            if current_start is None:
                current_start = point
            else:
                # If the current interval is not yet closed, check if the new start extends it
                if point <= current_end:
                    current_end = max(current_end, point)
                else:
                    merged.append([current_start, current_end])
                    current_start = point
                    current_end = point
        else:
            if current_start is not None:
                if point >= current_end:
                    merged.append([current_start, current_end])
                    current_start = None
                    current_end = None
                else:
                    current_end = max(current_end, point)

    if current_start is not None:
        merged.append([current_start, current_end])

    return merged

