def solve(n, edges):
    def dfs(node):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor)

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()
    components = 0

    for i in range(n):
        if i not in visited:
            dfs(i)
            components += 1

    return components

def solve(n, edges):
    parent = list(range(n))

    def.find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        root_u = .find(u)
        root_v = .find(v)
        if root_u != root_v:
            parent[root_v] = root_u

    for u, v in edges:
        union(u, v)

    components = set()
    for i in range(n):
